BEGIN;
update public.vihem_system_settings set value=jsonb_set(value,'{enabled}','false') where key='push_notification_dispatch';
create function pg_temp.expect(label text,ok boolean) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.reject(label text,statement text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;if not failed then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create temp table f(o uuid,o2 uuid,a uuid,s uuid,client uuid,client2 uuid,route uuid,op uuid,second uuid,t timestamptz);
do $$declare o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();r uuid:=gen_random_uuid();begin
 insert into public.vihem_organisations(id,name,slug) values(o,'QA Snow','snow-'||o),(o2,'QA Other Snow','snow-'||o2);
 insert into auth.users(id,email) values(a,a||'@example.invalid'),(s,s||'@example.invalid');
 insert into public.vihem_profiles(id,organisation_id,name,email,role,active) values(a,o,'Snow Admin',a||'@example.invalid','admin',true),(s,o,'Snow Staff',s||'@example.invalid','staff',true) on conflict(id) do update set organisation_id=excluded.organisation_id,role=excluded.role,active=true;
 insert into public.vihem_organisation_modules(organisation_id,module_key,enabled,settings) values(o,'snow',true,'{"admin_only":false}'),(o2,'snow',true,'{"admin_only":false}') on conflict(organisation_id,module_key) do update set enabled=true;
 insert into public.vihem_permission_grants(organisation_id,user_id,permission_key) values(o,s,'module.snow');
 insert into public.vihem_time_categories(organisation_id,key,label,active) values(o,'snow_plowing','Snöröjning',true),(o,'snow_sanding','Sandning',true) on conflict do nothing;
 insert into public.vihem_snow_clients(id,organisation_id,name) values(c,o,'SVEVIA VIRSERUM'),(c2,o2,'Other org client');
 insert into public.vihem_snow_routes(id,organisation_id,client_id,name,method,geometry) values(r,o,c,'Prio route','machine','{"type":"LineString","coordinates":[[15.58,57.31],[15.59,57.32]]}');
 insert into f values(o,o2,a,s,c,c2,r,gen_random_uuid(),gen_random_uuid(),now()-interval '20 minutes');
 perform set_config('request.jwt.claim.sub',s::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
end$$;
do $$declare other uuid:=gen_random_uuid();begin insert into auth.users(id,email) values(other,other||'@example.invalid');insert into public.vihem_profiles(id,organisation_id,name,email,role,active) select other,o2,'Other Organisation Driver',other||'@example.invalid','staff',true from f on conflict(id) do update set organisation_id=excluded.organisation_id,role='staff',active=true;end$$;
alter table f add column foreign_user uuid;update f set foreign_user=(select id from public.vihem_profiles where organisation_id=f.o2 limit 1);
grant select on f to authenticated;
update public.vihem_organisation_modules set settings=settings||'{"admin_only":true}'::jsonb where organisation_id=(select o from f) and module_key='snow';
set local role authenticated;
select pg_temp.reject('staff denied during admin pilot',format('select public.vihem_snow_availability_snapshot(%L,7)','2026-11-02'));
reset role;
select set_config('request.jwt.claim.sub',a::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.expect('admin snapshot is organisation-scoped',jsonb_array_length(public.vihem_snow_availability_snapshot('2026-11-02',7)->'people')=2);
select pg_temp.expect('roster excludes private profile fields',not exists(select 1 from jsonb_array_elements(public.vihem_snow_availability_snapshot('2026-11-02',7)->'people') p where p ? 'email' or p ? 'phone' or p ? 'bankid_personal_number'));
select pg_temp.expect('absence projection excludes reason',not ((public.vihem_snow_availability_snapshot('2026-11-02',7)->'absences')::text like '%absence_type%'));
select pg_temp.reject('snapshot date range is bounded',format('select public.vihem_snow_availability_snapshot(%L,100)','2026-11-02'));
do $$declare x record;op uuid:=gen_random_uuid();first jsonb;again jsonb;begin select * into x from f;
 first:=public.vihem_snow_availability_save(op,x.s,ARRAY['2026-11-02','2026-11-03']::date[],'partial','[[0,360],[1020,1440]]','{"2026-11-02":0,"2026-11-03":0}');
 again:=public.vihem_snow_availability_save(op,x.s,ARRAY['2026-11-02','2026-11-03']::date[],'partial','[[0,360],[1020,1440]]','{"2026-11-02":0,"2026-11-03":0}');
 perform pg_temp.expect('exact retry returns identical receipt',first=again);
 perform pg_temp.expect('two days saved once',(select count(*)=2 and max(revision)=1 from public.vihem_snow_availability where user_id=x.s));
 perform pg_temp.reject('receipt cannot be reused for another status',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',op,x.s,'2026-11-02','unavailable','[]','{"2026-11-02":1}'));
 perform pg_temp.reject('stale revision rejected',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),x.s,'2026-11-02','unavailable','[]','{"2026-11-02":0}'));
 perform pg_temp.reject('batch rollback when second day is stale',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L,%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),x.s,'2026-11-01','2026-11-02','available','[]','{"2026-11-01":0,"2026-11-02":0}'));
 perform pg_temp.expect('failed batch did not save first day',not exists(select 1 from public.vihem_snow_availability where user_id=x.s and work_date='2026-11-01'));
 perform pg_temp.reject('overlapping intervals rejected',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),x.s,'2026-11-04','partial','[[0,600],[500,900]]','{"2026-11-04":0}'));
 perform pg_temp.reject('cross-org target denied',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),x.foreign_user,'2026-11-04','available','[]','{"2026-11-04":0}'));
end$$;
select pg_temp.reject('direct writes denied even to admin',format('insert into public.vihem_snow_availability(organisation_id,user_id,work_date,status,updated_by) values(%L,%L,%L,%L,%L)',o,s,'2026-11-05','available',a)) from f;
reset role;
-- Optional staff access is tested only inside this rolled-back synthetic organisation.
update public.vihem_organisation_modules set settings=settings||'{"staff_availability_enabled":true}'::jsonb where organisation_id=(select o from f) and module_key='snow';
select set_config('request.jwt.claim.sub',s::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.expect('narrow staff access does not unlock snow jobs',public.vihem_snow_availability_access() and not public.vihem_snow_access());
select public.vihem_snow_availability_save(gen_random_uuid(),s,ARRAY['2026-11-06']::date[],'available','[]','{"2026-11-06":0}') from f;
select pg_temp.expect('full-day input normalized correctly',(select slots='[[0,1440]]'::jsonb from public.vihem_snow_availability where user_id=(select s from f) and work_date='2026-11-06'));
select pg_temp.reject('staff cannot change another driver',format('select public.vihem_snow_availability_save(%L,%L,ARRAY[%L]::date[],%L,%L::jsonb,%L::jsonb)',gen_random_uuid(),a,'2026-11-06','available','[]','{"2026-11-06":0}')) from f;
reset role;
update public.vihem_profiles set active=false where id=(select s from f);
set local role authenticated;
select pg_temp.reject('inactive identity denied',format('select public.vihem_snow_availability_snapshot(%L,7)','2026-11-02'));
reset role;
ROLLBACK;
